}) => any;

// Calcule l'indemnité légale de licenciement (L1234-9, R1234-1, R1234-2) à partir de l'ancienneté en mois et du salaire de référence mensuel brut en euros.
type indemnite_licenciement = (_: // indemnite_licenciement_input
{
// Anciennete Mois
//
// <PERSON> en mois complets.
anciennete_mois: integer, // minimum: 0
// <PERSON>
//
// <PERSON> de référence mensuel brut (€).
salaire_ref: <PERSON>, // minimum: 0.0
// Statut
//
// 'normal', 'faute_grave' ou 'faute_lourde'.
statut?: string, // default: "normal"
}) => any;
